# PTX source implementing fp16 sigmoid
PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry sigmoid_fp16(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u64 N
)
{
    .reg .pred   %p1;
    .reg .b64    %rd_in, %rd_out, %rd_N;
    .reg .b64    %rd_idx, %rd_stride, %rd_offset;
    .reg .b32    %tid, %bid, %blockDim, %gridDim, %tmp32;
    .reg .b16    %h_in, %h_out;
    .reg .f32    %f_in, %f_neg, %f_tmp, %f_den, %f_out;

    // Load kernel parameters
    ld.param.u64 %rd_in, [in_ptr];
    ld.param.u64 %rd_out, [out_ptr];
    ld.param.u64 %rd_N, [N];

    // Thread identifiers
    mov.u32 %tid, %tid.x;
    mov.u32 %bid, %ctaid.x;
    mov.u32 %blockDim, %ntid.x;
    mov.u32 %gridDim, %nctaid.x;

    // Linear thread index = blockIdx.x * blockDim.x + threadIdx.x
    mul.lo.u32 %tmp32, %bid, %blockDim;
    add.u32 %tmp32, %tmp32, %tid;
    cvt.u64.u32 %rd_idx, %tmp32;

    // Stride = gridDim.x * blockDim.x
    mul.lo.u32 %tmp32, %gridDim, %blockDim;
    cvt.u64.u32 %rd_stride, %tmp32;

LOOP:
    // while (idx < N)
    setp.lt.u64 %p1, %rd_idx, %rd_N;
    @!%p1 bra EXIT;

    // byte offset = idx * sizeof(half) (2)
    mul.lo.u64 %rd_offset, %rd_idx, 2;

    // Load half-precision element
    ld.global.b16 %h_in, [%rd_in + %rd_offset];

    // Convert to single precision for computation
    cvt.f32.f16 %f_in, %h_in;

    // Compute sigmoid: y = 1 / (1 + exp(-x))
    // Use ex2.approx for exp: exp(z) = 2^(z * log2(e))
    neg.f32 %f_neg, %f_in;
    mul.f32 %f_tmp, %f_neg, 1.4426950408889634;   // log2(e)
    ex2.approx.f32 %f_den, %f_tmp;               // exp(-x)
    add.f32 %f_den, %f_den, 1.0;
    rcp.approx.f32 %f_out, %f_den;               // 1 / (1+exp(-x))

    // Convert result back to half-precision (round-to-nearest)
    cvt.rn.f16.f32 %h_out, %f_out;

    // Store result
    st.global.b16 [%rd_out + %rd_offset], %h_out;

    // idx += stride
    add.u64 %rd_idx, %rd_idx, %rd_stride;
    bra LOOP;

EXIT:
    ret;
}
'''

# Python wrapper that loads and launches the kernel
import torch
import torch.nn as nn

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        # Load PTX module using the provided harness function
        self.module = ptx_load(PTX_SOURCE)
        self.block = (256, 1, 1)   # 256 threads per block

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is half‑precision
        if x.dtype != torch.float16:
            x = x.to(torch.float16)

        out = torch.empty_like(x, dtype=torch.float16)

        N = x.numel()
        grid_x = (N + self.block[0] - 1) // self.block[0]
        grid = (grid_x, 1, 1)

        # Arguments are raw 64‑bit pointers and the element count
        args = [int(x.data_ptr()), int(out.data_ptr()), int(N)]

        # Launch the kernel using the harness API
        ptx_launch(self.module, "sigmoid_fp16", grid, self.block, args)

        return out
